// ---- the settlements raised on 11 Nov 2026 to fill the empty country (ids gf_<realm>_<n>, in GAPN order) ----
(function () {
  var R = { stone: "Stonehold", ember: "Flameborne", storm: "Stormreach", light: "Lightforge", frost: "Frostgrave", spirit: "Spiritveil", shadow: "Shadowdeep", metal: "Metalcrown" };
  var D = {
    stone: [["Slatefell", "Slate quarries on the high fells; every roof in the north march is cut here.", "Quarrymen followed the slate seam up the fell and never came down. The village weighs each slate before it leaves, and writes the weight on the back."],
      ["Burdenmoor", "Where burden-stones are chosen: a moor of loose granite, and families walking it at dawn.", "Every Stonehold child comes here once to pick the stone they will carry for life. The moor is never short of stones, and nobody has ever seen one put back."],
      ["Cairnholt", "A hold built round a cairn older than the Long Roads.", "Nobody knows who raised the cairn. Cairnholt adds one stone a year and argues about whose turn it is."],
      ["Weighbridge", "The toll-scale on the north road; every cart is weighed, and so is its driver.", "The bridge's great beam was forged at the Prime Forge. The keepers say it has never been wrong, and keep a ledger of the times it nearly was."],
      ["Chiselby", "Apprentice carvers, practising names on scrap granite.", "Anvil Reach sends its apprentices out here to make their mistakes. The lanes are paved with misspelled names."],
      ["Greyshoulder", "A cliff village of Gravem-grey hands and patient goats.", "The cliff turns grey in the rain, and so, people say, does everyone who stays a winter."],
      ["Lintel Down", "Doorstones and lintels cut to order, delivered by ox.", "A lintel from Lintel Down is a wedding present in Stonehold. The village has never cut two the same."],
      ["Hallowstair", "A stair of ten thousand steps up to a watch-hold on the peak.", "The stair was cut by a garrison that would not wait for a road. Walkers count the steps aloud; most lose count near the top."]],
    ember: [["Kilnfold", "Kilns in a fold of black hills; the brick of Hearthmount's lower terraces.", "The kilns have never all been cold at once. Kilnfold tells the time by which one is being opened."],
      ["Ashwick", "Wick-makers and lamp-oil pressers on the ash plain.", "Ashwick wicks burn steady in a wind, and the village sells them with a promise it has never had to break."],
      ["Coalpit Green", "A green over old coal pits, where the grass grows warm.", "The pits were worked out a hundred years ago. The ground still smokes after rain, and the sheep stand on it in winter."],
      ["Glowmere", "A lake lit from beneath by a slow vein of fire.", "Fishers row out at night by the lake's own light. The fish come up cooked if you are patient, and nobody here is."],
      ["Brandmoor", "Horse-brands and cattle irons, forged and argued over.", "Every herd in western Flameborne wears a Brandmoor mark. Two families have disputed one brand for six generations."],
      ["Sootwell", "A deep well whose water runs black for a moment, then clear.", "Sootwell drinks only after the black has run. Strangers who do not wait are pointed at, kindly."],
      ["Emberleigh", "Orchards of cinder-plum on warm slopes.", "Emberleigh jam is boiled over vents in the ground, and tastes a little of smoke whatever you do."],
      ["Slagford", "A ford of old slag across a warm stream.", "The ford was built from the slag of a forge nobody remembers. It rings when carts cross it."]],
    storm: [["Gullreach", "A raft of nets and gulls at the end of the longest chain.", "Gullreach catches what the wind brings: fish, rope, now and then a lost hat from Skyrend."],
      ["Chainhollow", "A hollow of chain-moss where young skyrays graze.", "The moss grows thickest under the old chains. Chainhollow keeps them hung, though nothing has hung from them for years."],
      ["Squallmoor", "A moor-raft that tips in every storm; its people sleep in hammocks.", "Squallmoor has never had a level floor. Visitors fall over. Residents fall over less."],
      ["High Tether", "The anchor-post where three cliff-farms are tied to the rock.", "The tether-keepers walk the chains every morning and shout the count of links, loud enough to be heard on all three farms."],
      ["Windle", "Windmills that never stop, grinding barley for the north.", "Windle's mills turn whichever way the wind blows, which is every way, often at once."],
      ["Rafter's Rest", "A courier inn hung from the rafters of an old bridge.", "Couriers sleep standing up at Rafter's Rest, and pay for the privilege. The beds are for tourists."],
      ["Gustwick", "Kite-makers and weather-readers.", "A Gustwick kite will tell you the weather three days off. Whether you believe it is your business."],
      ["Linkhallow", "Where broken chain-links are melted and blessed back into chain.", "No link from Linkhallow has ever parted. The smiths say that is the wind's doing, and charge for it anyway."]],
    light: [["Lampwick", "The Rim market where antler-lamps and Rim candles are sold after dark.", "Lampwick grew where the Rim turns to evening. It is the only market in Lightforge that opens at dusk, and the busiest."],
      ["Whitecross", "A crossroads of white stone, swept every hour.", "Four roads meet at Whitecross, and four sweepers keep them white. The dust is carried away in sealed sacks and signed for."],
      ["Paleford", "A shallow ford over pale sand, watched by a witness on a stool.", "Every crossing at Paleford is witnessed and written down. Nobody has ever drowned there, and the records prove it."],
      ["Noonfield", "Sun-wheat grown under a noon that never moves.", "Noonfield's wheat ripens all year. The farmers take turns to rest, and argue about whose turn it is."],
      ["Clearbrook", "A brook so clear the village drinks it straight from the bank, and says so.", "Clearbrook has a law that no one may stir the brook. Children are taught to drink with their eyes open."],
      ["Gleamwick", "Glass lamp-chimneys, blown and polished.", "Gleamwick sells a chimney for every lamp in Lightforge and a second for when the first breaks."],
      ["Brasswell", "Brass sun-ovens, beaten and mended here.", "Brasswell's smiths can hear a dent in an oven from across the green. They will tell you which baker made it."],
      ["Daymere", "A mere that holds the noon light long after the Rim goes dark.", "On the Rim side of Daymere the water stays bright for an hour after dusk. Courting couples have opinions about that hour."]],
    frost: [["Rimeholt", "A hold of packed snow and knotted rope on the eastern ridge.", "Rimeholt keeps a cord for every winter it has stood. The oldest cord is black and stiff, and nobody will say how old."],
      ["Knotwell", "Knot-dyers by a warm spring that never freezes.", "The spring is the only open water for a day in any direction. Knotwell dyes its word-cords in it and says they keep their promises better."],
      ["Hoarstead", "A farm-steading where frost grows on the fences like feathers.", "Hoarstead's fences are never painted. The frost does it every morning, and better."],
      ["Coldharbour", "A harbour that freezes in a night and thaws in a morning.", "Coldharbour's boats are built to be dragged. The village has sailed on ice more often than on water."],
      ["Silverfen", "A fen of silver reeds and slow mammoths.", "The reeds bend toward the mammoths when they pass. Silverfen weaves them into roofs that last forty winters."],
      ["Stillmere", "A lake so still that people come to see their faces and stay to argue about them.", "Seers come to Stillmere and do not like what they read. The village sells them soup."],
      ["Thawbridge", "A bridge rebuilt every spring when the river takes the old one.", "Thawbridge has had four hundred bridges. The village names each one, and keeps a knot for it."],
      ["Cordwick", "Rope-walkers spinning cord in a long ice-shed.", "Cordwick spins the plain cord every knotwright buys. The best is spun by the oldest spinner, who will not say how."]],
    spirit: [["Willowmere", "The summer archives on the river, where the Lantern Council keeps its overflow.", "Willowmere floods, and everyone knows it floods. The archivists keep the shelves on stilts and the lamps on the top shelf."],
      ["Mistfold", "A valley where the mist folds over the roofs like a blanket.", "Mistfold rings a bell each hour so the village can find itself. Visitors are given a cord to hold."],
      ["Quillbrook", "Reed-pens cut along a brook for the Copying Rooms.", "Every copyist in Lanthys Vale writes with a Quillbrook reed. The village keeps one for every copyist who has died, in a jar by the door."],
      ["Paleglade", "A glade of pale birches where the old lamps are carried to rest.", "When a lamp is too old to shelve it comes to Paleglade, and is lit one last night among the birches."],
      ["Wickstead", "Wick-braiders and candle-dippers on the eastern road.", "Wickstead and Candlewick both claim to braid the best wick. Both are probably right."],
      ["Lampsend", "The last village before the Pale, where lamps are filled for the crossing.", "Lampsend fills every lantern that goes into the Pale and writes down who carried it. Most come back."],
      ["Greywillow", "A willow wood that remembers the names called in it.", "Call a name in Greywillow and it comes back the next morning. The village is careful whose names it calls."],
      ["Copyist's Rest", "A quiet inn for copyists whose eyes have given out.", "The old copyists at the Rest still correct the menu. The cook has stopped arguing."]],
    shadow: [["Murmur", "The rope-bridge city across the chasm from Hush.", "Murmur hangs on rope bridges over a chasm with no bottom anyone has found. It and Hush have argued about the Ledger Stair's lowest step for three hundred years."],
      ["Inkhollow", "Ink-pressers in a hollow where the inkroot grows wild.", "Inkhollow's ink will not fade. The village signs nothing in it, on principle."],
      ["Stillstair", "A long stair down to an underground lake, walked in silence.", "Nobody speaks on the Stillstair. Messages are passed by hand, and some have taken years to reach the bottom."],
      ["Undercliff", "Houses cut into the underside of a cliff, doors facing down.", "You reach Undercliff by rope. The village has never been raided, and has never been visited by anyone it did not expect."],
      ["Blindwater", "Fish-farms in black water, tended by touch.", "Blindwater's fish have no eyes, and neither, by choice, do its lamps. Visitors are given a hand to hold."],
      ["Ledger's Foot", "A village at the foot of a stair carved with debts.", "Ledger's Foot settles debts the Hollow Market will not. Nobody writes down what it charges."],
      ["Gloamwell", "A well that gives back the last thing said into it.", "Gloamwell's well keeps one secret at a time. The village takes turns."],
      ["Shuttered Row", "A street of shops that only open their shutters on the Night of Doors.", "The rest of the year Shuttered Row trades through a slot in each shutter. Nobody has seen most of the shopkeepers' faces."]],
    metal: [["Clinker Row", "Clinker-brick houses round a cooling yard.", "Clinker Row is built from the slag of Iron Throne City's first furnace. It is warm in winter and ringing in summer."],
      ["Smeltway", "The lit road of furnaces whose glow you can see from the city's chimneys.", "The Smeltway never sleeps. Children learn to read by its light."],
      ["Ashpipe", "A pipe-fitters' village under the city's waste-heat lines.", "Ashpipe's houses lean on the pipes for warmth. When a pipe is shut for repairs the whole village moves into the inn."],
      ["Boltmoor", "A moor of rusting bolts where old engines are taken apart.", "Nothing is thrown away at Boltmoor. The village names every engine it strips, and remembers what it did."],
      ["Gauge Hill", "Gauge-makers who test every measure in Metalcrown.", "Gauge Hill's master gauge has never been moved. The village built itself around it, and measures everything against it, including visitors."],
      ["Valve End", "The far end of the steam lines, where the valves are turned by hand.", "Valve End turns the city's heat up and down. It knows before anyone when a winter will be hard."],
      ["Sparkholm", "A holm in the river where synthetic sparks are tested.", "Sparkholm's tests light up the river at night. Fishers downstream have stopped complaining and started selling the view."],
      ["Plate Hollow", "Plate-rollers in a hollow where the noise can't reach the city.", "Plate Hollow rolls the thin plate for fittings. Its workers talk in signs, even at home."]]
  };
  var L = window.VHPLACELORE = window.VHPLACELORE || {};
  Object.keys(D).forEach(function (f) { D[f].forEach(function (e, i) { L["gf_" + f + "_" + i] = { name: e[0], realm: R[f], type: "settlement", known_for: e[1], history: e[2] }; }); });
})();
